export const ATTACHMENTS = [{"id":"cork-bobber","name":"Cork Bobber","slot":"bobber","rarity":"common","price":180,"flavor":"A stopper from a bottle of Harbor Red, sanded smooth by someone's thumb. It still smells faintly of celebration.","effects":{"biteRate":0.08}},{"id":"owl-feather-bobber","name":"Owl Feather Bobber","slot":"bobber","rarity":"uncommon","price":950,"flavor":"Shed by something enormous that patrols the meadow ponds at dusk. It refuses to bob loudly out of professional respect for silence.","effects":{"stability":0.15,"biteRate":0.05}},{"id":"glowshroom-bobber","name":"Glowshroom Bobber","slot":"bobber","rarity":"uncommon","price":1200,"flavor":"A hollowed cave mushroom that never stopped glowing, or complaining about the damp. Fish drift toward it like moths that forgot they were fish.","effects":{"biteRate":0.12}},{"id":"chime-bobber","name":"Chime Bobber","slot":"bobber","rarity":"rare","price":3400,"flavor":"A tiny glass bell that rings a note only fish can hear. The tinkerer hums along anyway, out of politeness.","effects":{"biteRate":0.2,"rareLuck":0.08}},{"id":"storm-glass-bobber","name":"Storm Glass Bobber","slot":"bobber","rarity":"epic","price":14500,"flavor":"Blown from lightning-fused sand off the trench coast, it sits level in any swell. The sea has tried everything; the sea is embarrassed.","effects":{"stability":0.3,"tension":0.2,"rareLuck":0.1}},{"id":"will-o-wisp-bobber","name":"Will-o'-Wisp Bobber","slot":"bobber","rarity":"legendary","price":62000,"flavor":"A swamp light coaxed into a lantern the size of a plum, still sulking about it. Things that have never been catalogued rise just to look.","effects":{"rareLuck":0.25,"biteRate":0.3}},{"id":"moonpool-bobber","name":"Moonpool Bobber","slot":"bobber","rarity":"mythic","price":260000,"flavor":"A droplet of the moon's reflection, skimmed from a glacier lake on the one night it held still. Where it floats, the water remembers being sky.","effects":{"rareLuck":0.4,"biteRate":0.35,"sizeBonus":0.25}},{"id":"barbed-hook","name":"Barbed Hook","slot":"hook","rarity":"common","price":260,"flavor":"It holds on the way your grandmother holds your cheek at harvest festival. The fish do not find this comparison comforting.","effects":{"stability":0.1}},{"id":"sewer-grate-hook","name":"Sewer Grate Hook","slot":"hook","rarity":"common","price":170,"flavor":"Bent from a city sewer grate by someone with strong opinions and stronger pliers. Whatever lives down there considers it local cuisine.","effects":{"biteRate":0.06,"goldBonus":0.05}},{"id":"twin-prong-hook","name":"Twin Prong Hook","slot":"hook","rarity":"rare","price":3900,"flavor":"Two hooks welded into an argument. Occasionally both of them win.","effects":{"multiCatch":0.08}},{"id":"gilded-hook","name":"Gilded Hook","slot":"hook","rarity":"rare","price":4800,"flavor":"Gold leaf over good steel, commissioned by a harbor merchant who believed fish respect wealth. Insultingly, he was right.","effects":{"goldBonus":0.25,"treasure":0.05}},{"id":"hydra-hook","name":"Hydra Hook","slot":"hook","rarity":"epic","price":16000,"flavor":"Cut one barb off and the smith swears two grew back. Nobody has tested this a third time.","effects":{"multiCatch":0.15,"biteRate":0.1}},{"id":"abyssal-hook","name":"Abyssal Hook","slot":"hook","rarity":"legendary","price":68000,"flavor":"Forged from trench iron that has never seen daylight and would rather keep it that way. It curves like a question the deep intends to answer.","effects":{"rareLuck":0.3,"tension":0.25,"sizeBonus":0.2}},{"id":"oiled-crank-reel","name":"Oiled Crank Reel","slot":"reel","rarity":"common","price":320,"flavor":"Squeaks in E flat, then in nothing, thanks to a generous helping of rig grease. The tinkerer calls this her masterpiece; she is being modest about the others.","effects":{"tension":0.1}},{"id":"flywheel-reel","name":"Flywheel Reel","slot":"reel","rarity":"uncommon","price":1300,"flavor":"Salvaged from a music box that used to play sea shanties. It still keeps the rhythm, which turns out to be most of reeling.","effects":{"tension":0.18}},{"id":"gyro-reel","name":"Gyro Reel","slot":"reel","rarity":"rare","price":4200,"flavor":"A spinning core keeps your rod steady through reef surge and rig-side chop. Hold it to your ear and you can hear it judging your posture.","effects":{"stability":0.3}},{"id":"dozing-reel","name":"Dozing Reel","slot":"reel","rarity":"rare","price":5600,"flavor":"It sets the hook while you watch the clouds, the kettle, or the inside of your eyelids. The tinkerer built it for her nap schedule and shares it reluctantly.","effects":{"autoReel":1,"tension":0.1}},{"id":"deep-current-winch","name":"Deep Current Winch","slot":"reel","rarity":"epic","price":18500,"flavor":"Unbolted from the old oil rig's crane, where it once hauled things the crew agreed never to discuss. It treats a thrashing marlin as light paperwork.","effects":{"tension":0.35,"sizeBonus":0.2}},{"id":"tide-turner-reel","name":"Tide-Turner Reel","slot":"reel","rarity":"legendary","price":48000,"flavor":"Its gears are cut from petrified whalebone and it winds with the patience of the tide itself. Fights don't get shorter; they simply stop being fights.","effects":{"stability":0.4,"tension":0.3,"xpBonus":0.15}},{"id":"chum-thermos","name":"Chum Thermos","slot":"gadget","rarity":"common","price":380,"flavor":"Keeps bait warm, fragrant, and deeply objectionable. Never, ever mix it up with your soup thermos.","effects":{"biteRate":0.1}},{"id":"lucky-cat-figurine","name":"Lucky Cat Figurine","slot":"gadget","rarity":"uncommon","price":850,"flavor":"A little porcelain cat that waves at your line from the tackle box. Coins seem to follow it home, along with actual cats.","effects":{"goldBonus":0.12}},{"id":"anglers-almanac","name":"Angler's Almanac","slot":"gadget","rarity":"uncommon","price":1450,"flavor":"Four hundred waterlogged pages of moon phases, feeding charts, and one recipe for chowder. Reading it in the rain counts as studying.","effects":{"xpBonus":0.15}},{"id":"spyglass-scope","name":"Spyglass Scope","slot":"gadget","rarity":"rare","price":2800,"flavor":"Clamp a retired pirate's spyglass to your rod and suddenly the horizon is casting distance. The deep water never saw you coming, because you were on the beach.","effects":{"scope":1}},{"id":"sonar-pinger","name":"Sonar Pinger","slot":"gadget","rarity":"epic","price":12500,"flavor":"Rig-salvage electronics that ping back the shape of whatever is eyeing your line. Sometimes the ping comes back nervous.","effects":{"sonar":1,"rareLuck":0.05}},{"id":"loadstone-magnet","name":"Loadstone Magnet","slot":"gadget","rarity":"epic","price":15500,"flavor":"A lodestone so opinionated it refuses to attract anything worthless. Old boots arrive as lockboxes; the boots are never mentioned again.","effects":{"magnet":1,"treasure":0.05}},{"id":"heart-of-the-trench","name":"Heart of the Trench","slot":"gadget","rarity":"mythic","price":285000,"flavor":"A fist-sized pearl that beats, slowly, in time with something far below the abyssal dark. Wear it on your belt and the ocean starts leaving you gifts, the way the sea leaves shells for children it likes.","effects":{"treasure":0.3,"rareLuck":0.3,"goldBonus":0.4}}];
export const BAITS = [{"id":"worm_basic","name":"Garden Worm","category":"worm","tier":1,"price":5,"flavor":"Dug fresh from behind the Brewery, much to the worm's ongoing surprise. The classic for a reason.","effects":{"biteRate":0.08}},{"id":"bakers_doughball","name":"Baker's Doughball","category":"dough","tier":1,"price":8,"flavor":"Day-old bread rolled with a little honey. Pond fish adore it; the baker pretends not to know where his scraps go.","effects":{"biteRate":0.1}},{"id":"meadow_cricket","name":"Meadow Cricket","category":"insect","tier":1,"price":12,"flavor":"Chirps right up until the cast, then goes professionally quiet. River fish consider it fine dining.","effects":{"biteRate":0.12}},{"id":"flash_minnow","name":"Flash Minnow","category":"minnow","tier":2,"price":40,"flavor":"A little silver show-off that catches the light on purpose. Bigger fish take it personally.","effects":{"biteRate":0.16}},{"id":"brine_shrimp","name":"Brine Shrimp","category":"shrimp","tier":2,"price":55,"flavor":"Salted, curled, and irresistible to anything with gills and ambition. Sold by the scoop at the harbor stall.","effects":{"biteRate":0.15,"rareLuck":0.05}},{"id":"tin_spinner","name":"Tin Spinner","category":"spinner","tier":3,"price":130,"flavor":"Hammered from an old kettle by the isle's tinker. It wobbles like injured prey and outlasts every worm you've ever loved.","effects":{"biteRate":0.2,"rareLuck":0.08}},{"id":"inkwell_squid","name":"Inkwell Squid","category":"squid","tier":3,"price":220,"flavor":"Leaves a dramatic little plume on the way down. Deep-sea hunters follow the ink like gossip.","effects":{"biteRate":0.24,"rareLuck":0.1}},{"id":"royal_nightcrawler","name":"Royal Nightcrawler","category":"worm","tier":4,"price":600,"flavor":"A worm of considerable breeding, raised on compost from the manor gardens. It expects to be taken by something impressive, and usually is.","effects":{"biteRate":0.3,"rareLuck":0.12}},{"id":"thunder_beetle","name":"Thunder Beetle","category":"insect","tier":4,"price":800,"flavor":"Carries a static charge that makes the water tingle for yards around. Fish arrive angry, which is convenient.","effects":{"biteRate":0.34,"rareLuck":0.1}},{"id":"gilded_krill","name":"Gilded Krill","category":"shrimp","tier":5,"price":2800,"flavor":"Each one is hand-brushed with edible gold leaf by a merchant who refuses to explain why it works. It works.","effects":{"biteRate":0.42,"rareLuck":0.2}},{"id":"glowgrub","name":"Glowgrub","category":"grub","tier":3,"farmOnly":true,"flavor":"Raised in the Bait Farm's mushroom beds until it glows a gentle cave-green. Fat, luminous, and deeply persuasive in dark water.","effects":{"biteRate":0.26,"rareLuck":0.12}},{"id":"prism_minnow","name":"Prism Minnow","category":"minnow","tier":4,"farmOnly":true,"flavor":"Bred in the Bait Farm's rainbow tanks; its scales split sunlight into colors that don't have names yet. Rare fish cross entire biomes to investigate.","effects":{"biteRate":0.32,"rareLuck":0.18}},{"id":"moonlit_mayfly","name":"Moonlit Mayfly","category":"magic","tier":4,"farmOnly":true,"flavor":"Hatches only under a full moon in the Bait Farm's night garden and lives for one perfect cast. Make it count.","effects":{"biteRate":0.36,"rareLuck":0.22}},{"id":"wisp_in_a_jar","name":"Wisp in a Jar","category":"magic","tier":5,"farmOnly":true,"flavor":"The Bait Farm's crowning oddity: a coaxed sliver of marsh-light that sings underwater. Legends rise to hear the end of the song.","effects":{"biteRate":0.48,"rareLuck":0.32}}];
export const POTIONS = [{"id":"pond_scum_pep","name":"Pond Scum Pep","color":"#7fb95c","flavor":"Technically it's algae tea, but the Brewer insists on calling it 'wetland espresso'. Fish find your hook noticeably more interesting; friends find your breath noticeably less.","ingredients":[{"kind":"rarity","value":"common","n":4}],"duration":10,"effects":{"biteRate":0.15}},{"id":"tiny_fry_tonic","name":"Tiny Fry Tonic","color":"#c9e265","flavor":"Six very small fish, one very small cauldron, one surprisingly large lesson about patience. Tastes like childhood summers and faintly of minnow.","ingredients":[{"kind":"sizeClass","value":"tiny","n":6}],"duration":15,"effects":{"xpBonus":0.15}},{"id":"river_runners_brew","name":"River Runner's Brew","color":"#5aa9d6","flavor":"Brewed at a rolling simmer because the river never sits still and neither should the pot. Drink it and the current starts whispering where the fish are hiding.","ingredients":[{"kind":"biome","value":"river","n":4}],"duration":15,"effects":{"biteRate":0.25}},{"id":"steady_sipping_syrup","name":"Steady Sipping Syrup","color":"#6bc4a6","flavor":"Thick as lake fog and twice as calm. The Brewer stirs it exactly once an hour, on principle, and your reeling hand learns the same restraint.","ingredients":[{"kind":"biome","value":"lake","n":3},{"kind":"rarity","value":"common","n":2}],"duration":15,"effects":{"stability":0.25}},{"id":"brackish_broth","name":"Brackish Broth","color":"#6b7a3f","flavor":"Smells like a swamp because it is, in every meaningful sense, a swamp. Somehow it settles the nerves the way only a warm bog can.","ingredients":[{"kind":"biome","value":"swamp","n":4}],"duration":20,"effects":{"stability":0.2,"biteRate":0.1}},{"id":"sewer_sheen","name":"Sewer Sheen","color":"#9da34b","flavor":"The Potion Brewer swears the shimmer is 'mostly minerals'. Whatever swims through the undercity apparently knows where all the loose coins settle.","ingredients":[{"kind":"biome","value":"sewer","n":3}],"duration":15,"effects":{"goldBonus":0.25}},{"id":"salt_spray_cordial","name":"Salt Spray Cordial","color":"#4fc3d9","flavor":"Bottled at high tide with a pinch of gull feather for luck. One sip and the bite window stretches out like a lazy cat in a sunbeam.","ingredients":[{"kind":"biome","value":"coast","n":4},{"kind":"rarity","value":"uncommon","n":2}],"duration":20,"effects":{"barSize":0.2}},{"id":"glacier_glaze","name":"Glacier Glaze","color":"#a8dcef","flavor":"Served cold, obviously; the Brewer once tried it warm and would rather not discuss it. Your hands go still as old ice and the fish stop noticing you're there.","ingredients":[{"kind":"biome","value":"glacier","n":4},{"kind":"sizeClass","value":"medium","n":2}],"duration":20,"effects":{"stability":0.35,"barSize":0.1}},{"id":"reef_rainbow_reduction","name":"Reef Rainbow Reduction","color":"#e86fa4","flavor":"Five reef fish, simmered until the pot starts humming in color. It never comes out the same shade twice, and neither does whatever bites next.","ingredients":[{"kind":"biome","value":"reef","n":5},{"kind":"rarity","value":"uncommon","n":3}],"duration":20,"effects":{"rareLuck":0.15,"biteRate":0.1}},{"id":"lanternlight_cordial","name":"Lanternlight Cordial","color":"#b47fe0","flavor":"Glows softly in the dark, like a nightlight for your stomach. Cave fish brewed with a rare catch teach your eyes to find what hides at the edges.","ingredients":[{"kind":"biome","value":"cave","n":3},{"kind":"rarity","value":"rare","n":1}],"duration":20,"effects":{"barSize":0.3,"rareLuck":0.1}},{"id":"big_fish_bisque","name":"Big Fish Bisque","color":"#d98e4a","flavor":"A hearty soup for anglers with hearty ambitions. Eat a big fish, become the kind of person big fish want to meet — the food chain is mostly confidence anyway.","ingredients":[{"kind":"sizeClass","value":"large","n":3},{"kind":"rarity","value":"rare","n":1}],"duration":20,"effects":{"sizeBonus":0.3}},{"id":"harbormasters_grog","name":"Harbormaster's Grog","color":"#caa64e","flavor":"The recipe is stamped, notarized, and slightly illegal in three ports. Everything you haul up afterwards seems to have a price tag and occasionally a padlock.","ingredients":[{"kind":"biome","value":"harbor","n":4},{"kind":"rarity","value":"rare","n":2}],"duration":25,"effects":{"goldBonus":0.4,"treasure":0.1}},{"id":"double_hook_decoction","name":"Double Hook Decoction","color":"#e0637a","flavor":"Brewed from fish that never learned to travel alone. Drink up and neither will your catches — the Brewery does not offer refunds for tangled lines.","ingredients":[{"kind":"rarity","value":"epic","n":2},{"kind":"sizeClass","value":"small","n":4}],"duration":15,"effects":{"multiCatch":0.15,"biteRate":0.15}},{"id":"abyssal_ink_elixir","name":"Abyssal Ink Elixir","color":"#3b2d5e","flavor":"It drinks you back, a little. The trench keeps its secrets in the dark, and for twenty-five minutes the dark decides you're trustworthy.","ingredients":[{"kind":"biome","value":"abyss","n":3},{"kind":"rarity","value":"epic","n":2}],"duration":25,"effects":{"rareLuck":0.3,"treasure":0.2}},{"id":"calderas_kiss","name":"Caldera's Kiss","color":"#e8542f","flavor":"Legendary scales dissolved in hot spring water, still gently boiling in the bottle. Whatever takes your hook afterwards will be built to match your new opinion of yourself.","ingredients":[{"kind":"biome","value":"volcanic","n":3},{"kind":"rarity","value":"legendary","n":1}],"duration":25,"effects":{"sizeBonus":0.45,"rareLuck":0.2}},{"id":"leviathans_lullaby","name":"Leviathan's Lullaby","color":"#46f0d2","flavor":"One mythic catch, two colossal ones, and a Brewer who didn't sleep for a week. The sea goes quiet when you uncork it — not empty, listening.","ingredients":[{"kind":"rarity","value":"mythic","n":1},{"kind":"sizeClass","value":"colossal","n":2},{"kind":"rarity","value":"legendary","n":2}],"duration":30,"effects":{"rareLuck":0.5,"multiCatch":0.25}}];
export const RODS = [{"id":"rod_t1","tier":1,"name":"Willow Switch","flavor":"A bendy stick, a length of string, and boundless optimism. The fish are not intimidated, which is exactly how you'll catch them.","cost":{"coins":0,"fish":[]},"stats":{"power":1,"biteRate":0,"rareLuck":0,"barSize":0,"stability":0,"slots":1}},{"id":"rod_t2","tier":2,"name":"Ashwood Angler","flavor":"Sanded smooth by someone who clearly cared, then sold to you by someone who clearly didn't. Smells faintly of campfires and second chances.","cost":{"coins":200,"fish":[{"kind":"rarity","value":"common","n":5}]},"stats":{"power":2,"biteRate":0.05,"rareLuck":0.02,"barSize":0.04,"stability":0.03,"slots":1}},{"id":"rod_t3","tier":3,"name":"Riverwarden's Cane","flavor":"Copper-ferruled and river-tested by three generations of wardens who all retired happy. The current whispers to it, and it politely whispers back.","cost":{"coins":600,"fish":[{"kind":"rarity","value":"common","n":10},{"kind":"biome","value":"river","n":3}]},"stats":{"power":3,"biteRate":0.1,"rareLuck":0.04,"barSize":0.08,"stability":0.06,"slots":2}},{"id":"rod_t4","tier":4,"name":"Lakekeeper's Longpole","flavor":"Long enough to reach the deep middle water where the smug fish live. Comes with a small brass bell that rings only when it feels like it.","cost":{"coins":1500,"fish":[{"kind":"rarity","value":"uncommon","n":5},{"kind":"biome","value":"lake","n":4}]},"stats":{"power":4,"biteRate":0.14,"rareLuck":0.07,"barSize":0.12,"stability":0.1,"slots":2}},{"id":"rod_t5","tier":5,"name":"Saltspray Longcast","flavor":"Whip it forward and the line sails clean past the breakers, humming a sailor's tune. The salt has cured the wood into something that no longer fears weather, or much of anything.","cost":{"coins":4000,"fish":[{"kind":"rarity","value":"uncommon","n":8},{"kind":"biome","value":"coast","n":5}]},"stats":{"power":5,"biteRate":0.18,"rareLuck":0.1,"barSize":0.16,"stability":0.14,"slots":2}},{"id":"rod_t6","tier":6,"name":"Coralsong Spire","flavor":"Grown, not built, in a reef garden where the polyps hum in harmony. Cast it and the water blooms with colour, as if the ocean is showing off for you.","cost":{"coins":9000,"fish":[{"kind":"rarity","value":"rare","n":3},{"kind":"biome","value":"reef","n":6}]},"stats":{"power":5,"biteRate":0.22,"rareLuck":0.14,"barSize":0.2,"stability":0.18,"slots":3}},{"id":"rod_t7","tier":7,"name":"Marshlight Snare","flavor":"Lacquered in swamp-witch resin and strung with sewer-silk, it glows a gentle green wherever honest light refuses to go. The murk holds no secrets from it, only appointments.","cost":{"coins":20000,"fish":[{"kind":"rarity","value":"rare","n":6},{"kind":"biome","value":"swamp","n":5},{"kind":"biome","value":"sewer","n":3}]},"stats":{"power":6,"biteRate":0.27,"rareLuck":0.18,"barSize":0.25,"stability":0.22,"slots":3}},{"id":"rod_t8","tier":8,"name":"Glacierheart Rod","flavor":"Its core is a sliver of thousand-year ice that refuses to melt out of sheer stubbornness. Hold it steady and the whole world seems to slow down and breathe.","cost":{"coins":45000,"fish":[{"kind":"rarity","value":"epic","n":2},{"kind":"biome","value":"glacier","n":6}]},"stats":{"power":7,"biteRate":0.32,"rareLuck":0.23,"barSize":0.3,"stability":0.27,"slots":3}},{"id":"rod_t9","tier":9,"name":"Rigline Colossus","flavor":"Welded from salvaged derrick steel and enough cable to moor a small nation. It doesn't cast so much as launch, and the deep sea has learned to take it seriously.","cost":{"coins":90000,"fish":[{"kind":"rarity","value":"epic","n":4},{"kind":"biome","value":"rig","n":5},{"kind":"biome","value":"deepsea","n":8}]},"stats":{"power":8,"biteRate":0.38,"rareLuck":0.28,"barSize":0.35,"stability":0.32,"slots":3}},{"id":"rod_t10","tier":10,"name":"Abysscaller","flavor":"Its line vanishes into black water and keeps going long after the ocean should have ended. Sometimes, when the night is very quiet, something at the other end tugs first.","cost":{"coins":180000,"fish":[{"kind":"rarity","value":"legendary","n":1},{"kind":"biome","value":"abyss","n":6}]},"stats":{"power":9,"biteRate":0.44,"rareLuck":0.34,"barSize":0.4,"stability":0.38,"slots":4}},{"id":"rod_t11","tier":11,"name":"Calderaforged Fang","flavor":"Quenched in a volcanic spring and cooled in a glacier lake, it still can't decide which one it prefers. The grip stays warm as fresh bread, even in a blizzard.","cost":{"coins":350000,"fish":[{"kind":"rarity","value":"legendary","n":3},{"kind":"rarity","value":"epic","n":10},{"kind":"biome","value":"volcanic","n":8}]},"stats":{"power":9,"biteRate":0.52,"rareLuck":0.42,"barSize":0.45,"stability":0.44,"slots":4}},{"id":"rod_t12","tier":12,"name":"The Leviathan's Toothpick","flavor":"Carved from a single rib of something the charts only call HERE BE, strung with a filament of dawn. When you cast it, the horizon leans in to watch.","cost":{"coins":700000,"fish":[{"kind":"rarity","value":"mythic","n":1},{"kind":"rarity","value":"legendary","n":5},{"kind":"biome","value":"abyss","n":10}]},"stats":{"power":10,"biteRate":0.6,"rareLuck":0.5,"barSize":0.5,"stability":0.5,"slots":4}}];
